/**
 * @name Path traversal in file operations
 * @description User-controlled data flowing to file operations without proper validation can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user input"

/**
 * @name Server-Side Request Forgery (SSRF)
 * @description Making HTTP requests to URLs controlled by user input can lead to SSRF attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("ClientSession").getReturn().getMember(["get", "post", "put", "delete", "patch", "request"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability: HTTP request to URL from $@.", source.getNode(), "user input"

/**
 * @name HTTP header injection
 * @description Injecting user input into HTTP headers can lead to response splitting and other attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/aiohttp-header-injection
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User input from aiohttp request attributes
    exists(DataFlow::AttrRead attr |
      attr.getObject().getALocalSource() = 
        API::moduleImport("aiohttp").getMember("web").getMember("Request").getReturn().asSource() and
      (
        attr.getAttributeName() = "query_string" or
        attr.getAttributeName() = "path" or
        attr.getAttributeName() = "query" or
        attr.getAttributeName() = "match_info" or
        attr.getAttributeName() = "cookies" or
        attr.getAttributeName() = "headers"
      ) and
      source = attr
    )
    or
    // General remote flow sources
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Response headers being set
    exists(DataFlow::CallCfgNode call |
      // Response.headers assignment or update
      call = API::moduleImport("aiohttp").getMember("web").getMember("Response").getReturn().getMember("headers").getMember(["__setitem__", "add", "extend", "update"]).getACall() and
      sink = call.getArg(_)
    )
    or
    // Direct header parameter in Response constructor
    exists(DataFlow::CallCfgNode response_call |
      response_call = API::moduleImport("aiohttp").getMember("web").getMember("Response").getACall() and
      sink = response_call.getArgByName("headers")
    )
    or
    // StreamResponse set_header methods
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("StreamResponse").getReturn().getMember(["set_cookie", "headers"]).getMember(["__setitem__", "add"]).getACall() and
      sink = call.getArg(_)
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Header injection from web request $@.", source.getNode(), "user input"

/**
 * @name Open redirect vulnerability
 * @description Redirecting to a user-controlled URL can lead to phishing attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/aiohttp-open-redirect
 * @tags security
 *        external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // HTTPFound, HTTPMovedPermanently, etc with location parameter
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember(["HTTPFound", "HTTPMovedPermanently", "HTTPSeeOther", "HTTPTemporaryRedirect", "HTTPPermanentRedirect"]).getACall() and
      (
        sink = call.getArg(0) or
        sink = call.getArgByName("location")
      )
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Open redirect from web request $@.", source.getNode(), "user input"
